const std = @import("std");
fn testWith(b: *std.Build, runner: std.Build.LazyPath, options: std.Build.TestOptions) *std.Build.Step.Compile { var configured = options; configured.test_runner = .{ .path = runner, .mode = .server }; return b.addTest(configured); }
pub fn build(b: *std.Build) void { const target = b.standardTargetOptions(.{}); const optimize = b.standardOptimizeOption(.{}); const dep = b.dependency("zigeffect_std", .{ .target = target, .optimize = optimize }); const module = b.addModule("zigeffect_s3", .{ .root_source_file = b.path("src/root.zig"), .target = target, .optimize = optimize, .imports = &.{.{ .name = "zigeffect_std", .module = dep.module("zigeffect_std") }} }); const tests = testWith(b, dep.module("zigeffect_test_runner").root_source_file.?, .{ .name = "zigeffect-s3-tests", .root_module = module }); b.step("test", "Run S3 adapter tests").dependOn(&b.addRunArtifact(tests).step); const port = b.option(u16, "port", "MinIO port") orelse 19000; const live_options = b.addOptions(); live_options.addOption(u16, "port", port); const live_module = b.createModule(.{ .root_source_file = b.path("tests/live_conformance.zig"), .target = target, .optimize = optimize, .imports = &.{ .{ .name = "zigeffect_s3", .module = module }, .{ .name = "live_options", .module = live_options.createModule() } } }); const live = testWith(b, dep.module("zigeffect_test_runner").root_source_file.?, .{ .name = "zigeffect-s3-live", .root_module = live_module }); b.step("conformance", "Run live S3 conformance").dependOn(&b.addRunArtifact(live).step); }
